完整版本如下，全部只用标准库：

```python
import unittest


def group_tasks(statuses, tasks):
    status_list = list(statuses)
    if any(type(status) is not str or not status for status in status_list):
        raise TypeError("statuses must contain non-empty strings")
    if len(set(status_list)) != len(status_list):
        raise ValueError("statuses must not contain duplicates")

    groups = {status: [] for status in status_list}
    for title, status in tasks:
        if status not in groups:
            raise ValueError(f"unknown status: {status}")
        groups[status].append(title)
    return groups


class GroupTasksTests(unittest.TestCase):
    def test_independent_lists(self):
        groups = group_tasks(
            ["todo", "doing", "done"],
            [("写摘要", "todo")],
        )
        self.assertEqual(
            groups,
            {"todo": ["写摘要"], "doing": [], "done": []},
        )
        self.assertEqual(len({id(value) for value in groups.values()}), 3)

    def test_preserves_task_order(self):
        self.assertEqual(
            group_tasks(
                ["todo"],
                [("第一项", "todo"), ("第二项", "todo")],
            ),
            {"todo": ["第一项", "第二项"]},
        )

    def test_accepts_status_generator(self):
        statuses = (status for status in ["todo", "done"])
        self.assertEqual(
            group_tasks(statuses, []),
            {"todo": [], "done": []},
        )

    def test_rejects_unknown_status(self):
        with self.assertRaisesRegex(ValueError, "unknown status: blocked"):
            group_tasks(["todo"], [("等待", "blocked")])

    def test_rejects_duplicate_statuses(self):
        with self.assertRaisesRegex(ValueError, "must not contain duplicates"):
            group_tasks(["todo", "todo"], [])


if __name__ == "__main__":
    unittest.main()
